WITH flattened AS (SELECT id, plan, currency, EXPLODE_OUTER(tier_prices) AS tier_value FROM price_tiers) SELECT currency, ROUND(AVG(tier_value), 2) AS avg_tier_value, ROUND(SUM(tier_value) / NULLIF(COUNT(CASE WHEN plan = 'starter' THEN 1 END), 0), 2) AS tier_value_per_starter, AVG(tier_value) FILTER (WHERE currency = 'EUR') AS eur_avg_tier_value, COUNT(DISTINCT plan) AS distinct_plans FROM flattened GROUP BY ROLLUP (currency) HAVING eur_avg_tier_value < 1000000;
